SELECT COUNT( `id` ) FROM `hydra_uofs_bucket`


    AND `user_identifier` = #{userIdentifier}


    AND `bucket_name` = #{bucketName}


    AND `bucket_identifier` = #{bucketIdentifier}

SELECT `id`, `guid`, `bucket_identifier` AS bucketIdentifier, `user_identifier` AS userIdentifier, `bucket_name` AS bucketName, `volume_guid` AS volumeGuid, `bucket_status` AS status, `ext_config` AS extConfig, `create_time` AS createTime, `update_time` AS updateTime
FROM `hydra_uofs_bucket`
WHERE `volume_guid` = #{volumeGuid}
ORDER BY `create_time` DESC, `id` DESC
LIMIT #{limit} OFFSET #{offset}

SELECT `id`, `guid`, `bucket_identifier` AS bucketIdentifier, `user_identifier` AS userIdentifier, `bucket_name` AS bucketName, `volume_guid` AS volumeGuid, `bucket_status` AS status, `ext_config` AS extConfig, `create_time` AS createTime, `update_time` AS updateTime
FROM `hydra_uofs_bucket`


    AND `user_identifier` = #{userIdentifier}


    AND `bucket_name` = #{bucketName}


    AND `bucket_identifier` = #{bucketIdentifier}


ORDER BY `create_time` DESC
LIMIT #{limit} OFFSET #{offset}
